sc_cat_item_producer.script:
/** This script is executed before the Record is generated
 * `current`- GlideRecord produced by Record Producer
 * Don't use `current.update()` or `current.insert()` as the record is generated by Record Producer
 * Don't use `current.setValue('sys_class_name', 'xxx')` as this will trigger reparent flow and can cause data loss
 * Avoid `current.setAbortAction()` and generate a separate record
 * Use `producer.var1` to access variables
 */
current.eleve = producer.eleve;

current.consentement_parental_verbal = producer.consentement_parental_verbal;

current.est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte = producer.est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte;

current.classe_distinct = producer.classe_distinct;

current.est_ce_que_l_l_ve_a_un_diagnostic_pos_par_un_professionnel_de_la_sant_autoris = producer.est_ce_que_l_l_ve_a_un_diagnostic;

current.situation_familiale_de_l_l_ve = producer.situation_familiale_de_l_l_ve;

current.short_description = "Communication alternative et améliorée Équipe Orthophonie TSA/Communication sociale: " + producer.eleve.getDisplayValue();

current.formulaire_d_aiguillage = producer.formulaire_d_aiguillage;
current.veuillez_ajouter_le_rapport_ou_la_recommandation_en_pi_ce_jointe = producer.veuillez_ajouter_le_rapport_ou_la_recommandation_en_pi_ce_jointe;

//current.autre_situation_explication = producer.autre_situation_explication;
